problem.solution:
// Solution
public class CircleArea {
    public static void main(String[] args) {
        double radius = 5.0;
        double area = Math.PI * Math.pow(radius, 2);
        System.out.println("Area: " + area); // Output: 78.53981633974483
    }
}
